// test_isotherm_fit.cpp
//
// Unit tests for the isotherm fitter (adsim/solver/isotherm_fit.h), which the
// Python package exposes as skarstrom.fit_isotherm. Synthetic data are generated BY THE ENGINE ITSELF (the same
// IsothermFunction code the solver uses, via isofit::Evaluate) from known
// parameters; the fitter must recover them -- exactly for noise-free data and
// within the reported uncertainty for noisy data.
//
// The parameter values below are arbitrary synthetic choices picked to give
// loadings of a few mol/kg over 0.01-10 bar; they do not describe any real
// adsorbent.

#include <cmath>
#include <random>
#include <string>
#include <utility>
#include <vector>

#include <gtest/gtest.h>

#include "adsim/equations/isotherm.h"

#include "adsim/solver/isotherm_fit.h"

namespace {

using adsim::IsothermType;
using adsim::isofit::FitResult;
using adsim::isofit::ParamSpec;
using adsim::isofit::Point;
using Values = std::vector<std::pair<std::string, double>>;

// Log-spaced pressures [Pa] at each temperature.
std::vector<Point> Grid(const std::vector<double>& temps, double p_lo, double p_hi, int n_per_t) {
  std::vector<Point> pts;
  for (double T : temps) {
    for (int i = 0; i < n_per_t; ++i) {
      const double f = static_cast<double>(i) / (n_per_t - 1);
      Point p;
      p.P = p_lo * std::pow(p_hi / p_lo, f);
      p.T = T;
      pts.push_back(p);
    }
  }
  return pts;
}

// Fill q from the engine isotherm, optionally with multiplicative Gaussian noise.
std::vector<Point> Synthesise(IsothermType kind, const Values& truth, std::vector<Point> pts,
                              double rel_noise = 0.0, unsigned seed = 7) {
  std::vector<double> q;
  std::string err;
  EXPECT_TRUE(adsim::isofit::Evaluate(kind, truth, pts, q, err)) << err;
  std::mt19937 rng(seed);
  std::normal_distribution<double> nd(0.0, 1.0);
  for (size_t i = 0; i < pts.size(); ++i) pts[i].q = q[i] * (1.0 + rel_noise * nd(rng));
  return pts;
}

FitResult FitDefault(IsothermType kind, const std::vector<Point>& pts) {
  std::vector<ParamSpec> specs;
  double t_ref = 0.0;
  std::string err;
  EXPECT_TRUE(adsim::isofit::DefaultSpecs(kind, pts, specs, t_ref, err)) << err;
  return adsim::isofit::Fit(kind, pts, specs, t_ref);
}

double ValueOf(const FitResult& r, const std::string& name) {
  for (const auto& p : r.params) if (p.name == name) return p.value;
  ADD_FAILURE() << "no parameter " << name;
  return std::nan("");
}

double SeOf(const FitResult& r, const std::string& name) {
  for (const auto& p : r.params) if (p.name == name) return p.std_error;
  return std::nan("");
}

bool FixedOf(const FitResult& r, const std::string& name) {
  for (const auto& p : r.params) if (p.name == name) return p.fixed;
  return false;
}

void ExpectRel(double got, double want, double rel, const std::string& what) {
  EXPECT_NEAR(got, want, std::abs(want) * rel) << what;
}

// Every predicted loading must reproduce the engine evaluated at the fitted
// parameters (i.e. q_fit really is the C++ isotherm, not a side calculation).
void ExpectQFitConsistent(IsothermType kind, const FitResult& r, const std::vector<Point>& pts) {
  Values v;
  for (const auto& p : r.params) v.emplace_back(p.name, p.value);
  std::vector<double> q;
  std::string err;
  ASSERT_TRUE(adsim::isofit::Evaluate(kind, v, pts, q, err)) << err;
  ASSERT_EQ(q.size(), r.q_fit.size());
  for (size_t i = 0; i < q.size(); ++i) EXPECT_DOUBLE_EQ(q[i], r.q_fit[i]);
}

}  // namespace

TEST(IsothermFit, HenryMultiTemperatureNoiseFree) {
  const Values truth = {{"k", 2.0e-9}, {"Q", 2.5e4}};
  const auto pts = Synthesise(IsothermType::HENRY, truth, Grid({273.15, 298.15, 323.15}, 1e3, 1e5, 8));
  const auto r = FitDefault(IsothermType::HENRY, pts);
  ASSERT_TRUE(r.ok) << r.error;
  ExpectRel(ValueOf(r, "k"), 2.0e-9, 1e-4, "k");
  ExpectRel(ValueOf(r, "Q"), 2.5e4, 1e-5, "Q");
  EXPECT_GT(r.r2, 1.0 - 1e-10);
  ExpectQFitConsistent(IsothermType::HENRY, r, pts);
}

TEST(IsothermFit, LangmuirSingleTemperatureFixesHeat) {
  // One temperature: q1 is not identifiable, so the defaults hold it at 0 and
  // fit the affinity at that temperature.
  const Values truth = {{"m1", 4.0}, {"b1", 2.0e-5}, {"q1", 0.0}};
  const auto pts = Synthesise(IsothermType::SINGLE_SITE_LANGMUIR_P, truth, Grid({303.15}, 1e3, 1e6, 15));
  const auto r = FitDefault(IsothermType::SINGLE_SITE_LANGMUIR_P, pts);
  ASSERT_TRUE(r.ok) << r.error;
  EXPECT_TRUE(FixedOf(r, "q1"));
  EXPECT_EQ(ValueOf(r, "q1"), 0.0);
  ExpectRel(ValueOf(r, "m1"), 4.0, 1e-5, "m1");
  ExpectRel(ValueOf(r, "b1"), 2.0e-5, 1e-5, "b1");
  EXPECT_LT(r.rmse, 1e-7);
  EXPECT_EQ(r.dof, 15 - 2);
  ExpectQFitConsistent(IsothermType::SINGLE_SITE_LANGMUIR_P, r, pts);
}

TEST(IsothermFit, LangmuirMultiTemperatureRecoversHeat) {
  const Values truth = {{"m1", 3.5}, {"b1", 1.0e-9}, {"q1", 2.8e4}};
  const auto pts =
      Synthesise(IsothermType::SINGLE_SITE_LANGMUIR_P, truth, Grid({283.15, 303.15, 323.15}, 1e3, 1e6, 10));
  const auto r = FitDefault(IsothermType::SINGLE_SITE_LANGMUIR_P, pts);
  ASSERT_TRUE(r.ok) << r.error;
  EXPECT_FALSE(FixedOf(r, "q1"));
  ExpectRel(ValueOf(r, "m1"), 3.5, 1e-4, "m1");
  ExpectRel(ValueOf(r, "b1"), 1.0e-9, 1e-3, "b1");
  ExpectRel(ValueOf(r, "q1"), 2.8e4, 1e-4, "q1");
  EXPECT_GT(r.r2, 1.0 - 1e-10);
}

TEST(IsothermFit, DualSiteLangmuirMultiTemperature) {
  const Values truth = {{"m1", 1.5}, {"b1", 5.0e-10}, {"q1", 3.2e4},
                        {"m2", 3.0}, {"b2", 2.0e-9}, {"q2", 1.8e4}};
  const auto pts =
      Synthesise(IsothermType::DUAL_SITE_LANGMUIR_P, truth, Grid({273.15, 298.15, 323.15}, 1e2, 2e6, 14));
  const auto r = FitDefault(IsothermType::DUAL_SITE_LANGMUIR_P, pts);
  ASSERT_TRUE(r.ok) << r.error;
  double q_max = 0.0;
  for (const auto& p : pts) q_max = std::max(q_max, p.q);
  // Dual-site fits are only identifiable up to swapping the sites; check the
  // fit quality and the two sites as an unordered pair.
  EXPECT_LT(r.rmse, 1e-4 * q_max);
  const bool swapped = ValueOf(r, "m1") > ValueOf(r, "m2");
  const std::string s1 = swapped ? "2" : "1", s2 = swapped ? "1" : "2";
  ExpectRel(ValueOf(r, "m" + s1), 1.5, 0.02, "m (site 1)");
  ExpectRel(ValueOf(r, "m" + s2), 3.0, 0.02, "m (site 2)");
  ExpectRel(ValueOf(r, "q" + s1), 3.2e4, 0.02, "q (site 1)");
  ExpectRel(ValueOf(r, "q" + s2), 1.8e4, 0.02, "q (site 2)");
}

TEST(IsothermFit, SipsSingleTemperature) {
  const Values truth = {{"q_sat", 5.0}, {"b", 3.0e-6}, {"v", 1.6}};
  const auto pts = Synthesise(IsothermType::SIPS, truth, Grid({298.15}, 1e3, 3e6, 16));
  const auto r = FitDefault(IsothermType::SIPS, pts);
  ASSERT_TRUE(r.ok) << r.error;
  ExpectRel(ValueOf(r, "q_sat"), 5.0, 1e-4, "q_sat");
  ExpectRel(ValueOf(r, "b"), 3.0e-6, 1e-3, "b");
  ExpectRel(ValueOf(r, "v"), 1.6, 1e-4, "v");
}

TEST(IsothermFit, TothSingleTemperature) {
  const Values truth = {{"q_sat", 6.0}, {"b", 1.0e-5}, {"v", 0.45}};
  const auto pts = Synthesise(IsothermType::TOTH, truth, Grid({298.15}, 1e2, 2e6, 16));
  const auto r = FitDefault(IsothermType::TOTH, pts);
  ASSERT_TRUE(r.ok) << r.error;
  ExpectRel(ValueOf(r, "q_sat"), 6.0, 1e-3, "q_sat");
  ExpectRel(ValueOf(r, "b"), 1.0e-5, 1e-3, "b");
  ExpectRel(ValueOf(r, "v"), 0.45, 1e-3, "v");
}

TEST(IsothermFit, Sips2MultiTemperature) {
  // T_ref is held at the (rounded) mean data temperature by the defaults, so
  // the synthetic truth uses that same reference.
  const auto grid = Grid({288.15, 308.15, 328.15}, 1e3, 2e6, 12);
  const Values truth = {{"A1", 4.0}, {"A2", -0.8}, {"B1", 4.0e-9}, {"B2", 2.2e4},
                        {"C1", 0.85}, {"C2", 0.6}, {"T_ref", 308.15}};
  const auto pts = Synthesise(IsothermType::SIPS_2, truth, grid);
  const auto r = FitDefault(IsothermType::SIPS_2, pts);
  ASSERT_TRUE(r.ok) << r.error;
  EXPECT_DOUBLE_EQ(ValueOf(r, "T_ref"), 308.15);
  EXPECT_TRUE(FixedOf(r, "T_ref"));
  double q_max = 0.0;
  for (const auto& p : pts) q_max = std::max(q_max, p.q);
  EXPECT_LT(r.rmse, 1e-4 * q_max);
  ExpectRel(ValueOf(r, "A1"), 4.0, 0.01, "A1");
  EXPECT_NEAR(ValueOf(r, "A2"), -0.8, 0.02);
  ExpectRel(ValueOf(r, "B2"), 2.2e4, 0.01, "B2");
  ExpectRel(ValueOf(r, "C1"), 0.85, 0.01, "C1");
  EXPECT_NEAR(ValueOf(r, "C2"), 0.6, 0.02);
}

TEST(IsothermFit, Toth2MultiTemperature) {
  const auto grid = Grid({283.15, 303.15, 323.15}, 1e2, 2e6, 12);
  const Values truth = {{"q_sat", 5.0}, {"x", 2.0}, {"T_0", 303.15}, {"b0", 2.0e-5},
                        {"dH0", 2.6e4}, {"w0", 0.55}, {"alpha", 0.3}};
  const auto pts = Synthesise(IsothermType::TOTH_2, truth, grid);
  const auto r = FitDefault(IsothermType::TOTH_2, pts);
  ASSERT_TRUE(r.ok) << r.error;
  double q_max = 0.0;
  for (const auto& p : pts) q_max = std::max(q_max, p.q);
  EXPECT_LT(r.rmse, 1e-4 * q_max);
  ExpectRel(ValueOf(r, "q_sat"), 5.0, 0.02, "q_sat");
  ExpectRel(ValueOf(r, "b0"), 2.0e-5, 0.02, "b0");
  ExpectRel(ValueOf(r, "dH0"), 2.6e4, 0.02, "dH0");
  ExpectRel(ValueOf(r, "w0"), 0.55, 0.02, "w0");
}

TEST(IsothermFit, NoisyLangmuirWithinUncertainty) {
  const Values truth = {{"m1", 3.5}, {"b1", 1.0e-9}, {"q1", 2.8e4}};
  const auto pts = Synthesise(IsothermType::SINGLE_SITE_LANGMUIR_P, truth,
                              Grid({283.15, 303.15, 323.15}, 1e3, 1e6, 12), /*rel_noise=*/0.01);
  const auto r = FitDefault(IsothermType::SINGLE_SITE_LANGMUIR_P, pts);
  ASSERT_TRUE(r.ok) << r.error;
  EXPECT_GT(r.r2, 0.995);
  for (const auto& [name, want] : std::vector<std::pair<std::string, double>>{{"m1", 3.5}, {"q1", 2.8e4}}) {
    const double se = SeOf(r, name);
    ASSERT_TRUE(std::isfinite(se)) << name;
    EXPECT_GT(se, 0.0) << name;
    // Within 4 standard errors (and the estimate itself must be sane).
    EXPECT_LT(std::abs(ValueOf(r, name) - want), 4.0 * se) << name << " se=" << se;
    EXPECT_LT(se, 0.1 * want) << name;
  }
}

TEST(IsothermFit, NoisySipsCloseToTruth) {
  const Values truth = {{"q_sat", 5.0}, {"b", 3.0e-6}, {"v", 1.6}};
  const auto pts = Synthesise(IsothermType::SIPS, truth, Grid({298.15}, 1e3, 3e6, 25), 0.01, 11);
  const auto r = FitDefault(IsothermType::SIPS, pts);
  ASSERT_TRUE(r.ok) << r.error;
  EXPECT_GT(r.r2, 0.995);
  ExpectRel(ValueOf(r, "q_sat"), 5.0, 0.1, "q_sat");
  ExpectRel(ValueOf(r, "v"), 1.6, 0.1, "v");
  for (const auto& n : {"q_sat", "b", "v"}) EXPECT_TRUE(std::isfinite(SeOf(r, n))) << n;
}

TEST(IsothermFit, UserFixedParameterIsHeld) {
  const Values truth = {{"m1", 4.0}, {"b1", 1.0e-9}, {"q1", 2.5e4}};
  const auto pts = Synthesise(IsothermType::SINGLE_SITE_LANGMUIR_P, truth, Grid({298.15}, 1e3, 1e6, 12));
  std::vector<ParamSpec> specs;
  double t_ref = 0.0;
  std::string err;
  ASSERT_TRUE(adsim::isofit::DefaultSpecs(IsothermType::SINGLE_SITE_LANGMUIR_P, pts, specs, t_ref, err));
  for (auto& s : specs) if (s.name == "q1") { s.value = 2.5e4; s.fixed = true; }
  const auto r = adsim::isofit::Fit(IsothermType::SINGLE_SITE_LANGMUIR_P, pts, specs, t_ref);
  ASSERT_TRUE(r.ok) << r.error;
  EXPECT_DOUBLE_EQ(ValueOf(r, "q1"), 2.5e4);
  ExpectRel(ValueOf(r, "m1"), 4.0, 1e-4, "m1");
  ExpectRel(ValueOf(r, "b1"), 1.0e-9, 1e-3, "b1");
}

TEST(IsothermFit, Errors) {
  const auto pts = Synthesise(IsothermType::SIPS, {{"q_sat", 5.0}, {"b", 3e-6}, {"v", 1.0}},
                              Grid({298.15}, 1e3, 1e6, 2));
  // Two points cannot pin three free parameters.
  const auto r = FitDefault(IsothermType::SIPS, pts);
  EXPECT_FALSE(r.ok);
  EXPECT_NE(r.error.find("at least 3"), std::string::npos) << r.error;

  std::vector<ParamSpec> specs;
  double t_ref = 0.0;
  std::string err;
  EXPECT_FALSE(adsim::isofit::DefaultSpecs(IsothermType::ARRHENIUS_SIPS, pts, specs, t_ref, err));
  EXPECT_FALSE(err.empty());

  ParamSpec bogus;
  bogus.name = "nope";
  const auto r2 = adsim::isofit::Fit(IsothermType::SIPS, pts, {bogus});
  EXPECT_FALSE(r2.ok);

  std::vector<Point> none;
  EXPECT_FALSE(adsim::isofit::DefaultSpecs(IsothermType::SIPS, none, specs, t_ref, err));
}
